from author import *
c=C('计算机网络总览与分层模型')
S(c,'课程导学与十章知识地图',[T('学习路线','先建立分层地图，再逐层学协议，最后做计算题'),T('课程重点','分层模型、子网划分、路由转发、TCP可靠传输与拥塞控制')],[P('这一小时，我们从一个网页请求开始，把计算机网络的主线串起来。先认识分层模型和性能指标，再顺着数据发送的顺序，逐层学习物理层、数据链路层、网络层、传输层和应用层，最后用综合例题把子网划分、路由转发、TCP握手和拥塞控制串起来。每章留一道练习，先自己判断，再看下一页答案。本课搭框架，不代替完整教材。',[1,2],['先建立分层地图','每章练习先判断再看答案'],show=2)],['课程导学'],kind='overview')

S(c,'计算机网络是什么',[T('网络边缘','手机、电脑和服务器等端系统，产生和接收数据'),T('网络核心','交换机与路由器等转发设备，负责把数据送过去'),T('网络分类','按覆盖范围分为局域网、城域网和广域网')],[P('先看一个小场景：你在宿舍用手机打开学校的选课网站。手机是通信的一端，学校服务器是另一端，中间经过无线接入点、交换机和路由器。手机和服务器这类真正产生数据的设备，叫网络边缘，也叫端系统；中间负责转发数据的设备，叫网络核心。网络就是用硬件和规则，让边缘这些设备互相传递数据。',[1,2],['先分清端系统和转发设备','产生数据和转发数据是两种角色']),P('再看分类。覆盖一个房间、一栋楼或一个校园的是局域网，通常由使用它的组织自己管理；覆盖一座城市规模的是城域网；跨越城市甚至国家的是广域网，互联网就是最大的广域网。分类依据是覆盖范围和管理方式，不是设备价格。宿舍自己布的网线属于局域网，访问外网还要经过路由器和运营商网络。',[3],['按覆盖范围划分网络','局域网可以接入广域网'])],['网络组成','网络分类'])

S(c,'性能指标：带宽、吞吐量与时延',[T('带宽与吞吐量','带宽是链路能力上限，吞吐量是实际传送量'),T('发送时延','分组长度除以链路带宽，与数据量和速率有关'),T('传播时延','链路长度除以传播速度，与距离和介质有关')],[P('衡量网络快慢，先分清几个指标。带宽描述一条链路在单位时间内的传送能力上限，吞吐量是实际传送成功的多少。真正感受到的端到端时延由四部分相加：发送时延、传播时延、处理时延和排队时延。例如一个一千字节的分组就是八千比特，经过一条一兆比特每秒的链路，发送时延等于八千除以一兆，结果是八毫秒。',[1,2],['先算发送时延','区分能力上限和实际结果'],phase='send',anchor='发送时延等于八千除以一兆'),P('如果这段链路长两千公里，信号在介质中以每秒两亿米的速度传播，传播时延等于两千万米除以两亿米每秒，结果是十毫秒。所以升级带宽只能压缩发送时延，传播时延由距离和介质决定。做计算题时，先判断问的是哪一段时延，再代入公式，不要把所有等待都笼统叫作网速慢。',[3],['传播时延与距离有关','先判断再代公式'],phase='prop',anchor='传播时延等于两千万米除以两亿米每秒')],['性能指标','时延计算'],visual=G('delay'))

S(c,'分层思想与协议栈',[T('分层','把复杂问题拆成若干层，每层只解决一类问题'),T('协议','同层对等实体之间通信时遵守的规则'),T('封装与解封装','逐层加首部，接收方再逐层去掉首部')],[P('分层是把复杂问题拆开的办法。想象寄快递：你只负责把物品装进箱子、写清收件地址；快递公司负责运输和中转；收件人负责拆箱验货。每一方只关心自己的任务，不需要知道别人的全部细节。网络也一样，应用层产生数据，传输层负责端到端交付，网络层负责寻址和转发，链路层负责送过一段链路。',[1,2],['每层只解决一类问题','下一层的细节对上透明'],phase='encap',anchor='你只负责把物品装进箱子'),P('同一层的两个对等实体之间通信，要遵守共同的规则，这就是协议。相邻两层通过接口交换数据：上层把整块数据交给下层，下层把它当作数据部分，再加上自己的首部，这叫封装。接收方从物理层向上，每层去掉自己的首部交给上层，叫解封装。每一层都在为上层提供服务，同时使用下层提供的服务。',[3],['协议约束同层通信','封装和解封装方向相反'],phase='decap',anchor='每一层都在为上层提供服务')],['分层与协议','封装'],visual=G('stack'))

S(c,'OSI七层与TCP/IP四层',[T('OSI参考模型','物理、数据链路、网络、传输、会话、表示、应用'),T('TCP/IP四层','网络接口、网际、传输、应用'),T('对应关系','会话与表示并入应用层，物理与链路合为网络接口层')],[P('教材里常出现两套分层模型。OSI参考模型分为七层：物理层、数据链路层、网络层、传输层、会话层、表示层、应用层。它的好处是概念清楚，便于描述每层职责，但它更多是理论参考，不等于实际运行的协议栈。互联网实际使用TCP/IP模型，把会话层和表示层并入应用层，把物理层和数据链路层合称网络接口层，于是变成四层。',[1,2],['OSI是参考模型','实际使用TCP/IP模型']),P('两套模型的对应关系是常考点。看到OSI的会话层和表示层，对应到TCP/IP的应用层；看到物理层和数据链路层，对应到网络接口层。学习时不要只背七层名称，而要能说出每层解决什么问题：物理层传比特，链路层传帧，网络层传分组，传输层传报文段，应用层处理具体应用。后面章节就按这个顺序展开。',[3],['按功能对应两套模型','记住每层传什么数据单位'])],['分层模型','OSI与TCP/IP'])

S(c,'封装与解封装的完整过程',[T('发送方','应用数据逐层加首部，形成各层的数据单元'),T('接收方','逐层检查并去掉首部，交给上一层'),T('地址的作用范围','MAC地址管同一链路，IP地址管跨网络，端口号管进程')],[P('现在把封装过程走一遍。你在浏览器里请求网页，应用层生成HTTP请求报文。传输层加上TCP首部，标明源端口和目的端口，形成报文段。网络层加上IP首部，标明源IP和目的IP，形成IP分组。链路层再加帧首部和帧尾，标明源MAC和目的MAC，形成帧。物理层把帧变成信号发送出去，每往下一层就多一层首部。',[1],['每下一层就多一个首部','首部只在对应层有用']),P('接收方做相反的事：物理层把信号还原成帧，链路层检查并去掉帧首尾，网络层去掉IP首部，传输层去掉TCP首部，最后应用层拿到HTTP报文解析。这里有个常考点：不同层地址的作用范围不同。MAC地址只在同一段链路内有效，跨路由器会被重新封装；IP地址负责端到端寻址，转发中基本不变；端口号区分不同应用进程。',[2,3],['MAC地址逐段链路有效','IP地址端到端基本不变','端口号区分应用进程'])],['封装过程','地址作用范围'])

S(c,'分层与时延练习',[T('场景','主机A请求主机B上的一个网页'),T('问题一','按TCP/IP四层模型，发送方至少要加几次首部'),T('问题二','只把链路带宽提升十倍，传播时延会变小吗')],[P('暂停一下，用刚才的分层和时延理解做两个判断。第一问：主机A向主机B发送网页请求，数据在发送方从应用层走到物理层，按TCP/IP四层模型，至少要加几次首部。第二问：把链路带宽从一兆提升到十兆，端到端时延里的传播时延会不会变小。请分别写出答案和依据，先自己判断，再翻到下一页对照。',[1,2,3],['先数封装层次','再找传播时延的决定因素'])],['分层练习'],kind='question')

S(c,'分层与时延练习答案',[T('第一问','三次：传输层、网际层、网络接口层各加首部'),T('第二问','不会，带宽只影响发送时延'),T('检查方法','按层数数首部，按时延来源选公式')],[P('第一问：按TCP/IP四层模型，应用层数据在传输层加TCP首部、在网际层加IP首部、在网络接口层加帧首部和帧尾，所以是三次加首部；若题目按OSI七层模型问，就要按题目层数说明。第二问：传播时延等于链路长度除以信号传播速度，只由距离和介质决定，带宽变大只影响发送时延。这两问分别考查封装层次和时延来源。',[1,2,3],['先数层次再加首部','传播时延看距离'])],['分层练习'],kind='answer')
